{
  "findings": [
    {
      "check_id": "CKV_AWS_144",
      "title": "S3 bucket does not have cross-region replication enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket financials does not have cross-region replication configured, which may lead to data loss in case of a region-specific disaster."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket does not have object lock enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket financials does not have object lock enabled, which may lead to data being overwritten or deleted unintentionally."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket does not have versioning enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket financials does not have versioning enabled, making it difficult to recover from accidental deletion or overwrite."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "financials" {
  bucket        = "${local.resource_prefix.value}-financials"
  acl           = "private"
  force_destroy = true
  versioning {
    enabled = true
  }
  tags = merge({
    Name        = "${local.resource_prefix.value}-financials"
    Environment = local.resource_prefix.value
    }, {
  })
}
resource "aws_s3_bucket_replication_configuration" "financials_replication" {
  bucket = aws_s3_bucket.financials.id
  role   = aws_iam_role.replication.arn
  rule {
    status = "Enabled"
    destination {
      bucket        = "arn:aws:s3:::financials-replication-${local.resource_prefix.value}"
      storage_class = "STANDARD"
    }
  }
}
resource "aws_s3_bucket_object_lock_configuration" "financials_object_lock" {
  bucket = aws_s3_bucket.financials.id
  rule {
    default_retention {
      mode = "COMPLIANCE"
      days = 365
    }
  }
}",
  "fix_summary": "Enabled versioning on the S3 bucket, added a replication configuration, and enabled object lock to improve data durability and protection."
}
